    24	// authForms returns every representation a basic-auth credential took on the
    25	// wire, so all of them can be scrubbed from an echoed response: the raw
    26	// secret, its URL-encoded form (as it appears in a form body or URL), and the
    27	// complete `Authorization: Basic` value base64(user:pass). Redacting only the
    28	// literal secret would let an endpoint that echoes the authorization header —
    29	// or any encoded rendition of the request — leak the credential verbatim.
    30	func authForms(user, pass string) []string {
    31		return []string{
    32			pass,
    33			url.QueryEscape(pass),
    34			base64.StdEncoding.EncodeToString([]byte(user + ":" + pass)),
    35		}
    36	}

